let MASTER=null,PAYM=null,PROP=null;
(function w(){if(typeof db!=='undefined'&&db&&db.doc){db.doc('config/qbitems').onSnapshot(s=>{MASTER=(s.data()||{}).items||null;if(AME.cur==='bid'&&cur())render()},()=>{});db.doc('config/qbpayroll').onSnapshot(s=>{PAYM=(s.data()||{}).pay||null},()=>{});db.doc('config/qbproposal').onSnapshot(s=>{PROP=(s.data()||{}).t||null},()=>{})}else setTimeout(w,400)})();
const master=()=>MASTER||[];
/* ---------- bid defaults / calc ---------- */
function bd_(p){const bd=p.bid=p.bid||{};bd.lines=bd.lines||{};bd.extra=bd.extra||[];if(bd.tax==null)bd.tax=7.75;if(bd.oh==null)bd.oh=10;if(bd.profit==null)bd.profit=10;if(bd.op==null)bd.op=0;if(bd.rnd==null)bd.rnd=100;bd.mm=bd.mm||'straight';if(bd.hpd==null)bd.hpd=8;if(bd.dpw==null)bd.dpw=5;bd.mk=bd.mk||{};bd.ind=bd.ind||{stock:0,clean:0,sup:0,pd:0};bd.add=bd.add||[];bd.alts=bd.alts||[];bd.pay=bd.pay||JSON.parse(JSON.stringify(PAYM||PAY_DEF));bd.cover=bd.cover||{};bd.extra.forEach(x=>{if(!x.cat)x.cat='eqp'});return bd}
function rateOf(bd,pc,wt){const c=(bd.pay.cls||[]).find(x=>x.n===pc);if(!c)return 0;const base=num((c.w||{})[wt||'Regular'])||num((c.w||{}).Regular);const bur=(bd.pay.bur||[]).reduce((a,b)=>a+num(b.v),0);return base*(1+bur/100)}
const altOn=(bd,a)=>!a||(bd.alts.find(x=>x.id===a)||{}).acc;
function lcalc(p,bd,c,l){const Q=condQty(p,c);let q=Q.q;const mt=l.mt||'std';let L=l;if(mt==='q2'||mt==='q3'){const R=P.condRes(p,c);const v=R.vals[mt==='q2'?1:2];q=v?v.v:0;L={...l,mt:'std'}}
  if(!num(l.wr)&&!num(l.l)&&l.pc){L={...L,wr:rateOf(bd,l.pc,l.wt)}}if(l.prod==='day'&&num(l.qh)){L={...L,qh:num(l.qh)/num(bd.hpd||8)}}
  const r=lineCost(L,q,bd);if(num(bd.labAdj))r.lb*=1+num(bd.labAdj)/100;r.ctr=num(l.ctr)?Math.ceil(r.qty/num(l.ctr)):0;if(l.rndc&&num(l.ctr))r.m=r.ctr*num(l.ctr)*num(l.m)/((l.per===''||l.per==null)?1:num(l.per));return r}
function calc(p){const bd=bd_(p);const T={mat:0,lab:0,sub:0,cost:0,eqp:0,oth:0,hrs:0,byC:{},byA:{},byCC:{},byAlt:{}};
  p.conds.forEach(c=>{const{q}=condQty(p,c);const L=bd.lines[c.id]||[];const row={q,mat:0,lab:0,hrs:0,n:L.length};L.forEach(l=>{if(!altOn(bd,l.alt)){const a=T.byAlt[l.alt]=T.byAlt[l.alt]||{mat:0,lab:0,oth:0};const r=lcalc(p,bd,c,l);a.mat+=r.m;a.lab+=r.lb;return}const r=lcalc(p,bd,c,l);row.mat+=r.m;row.lab+=r.lb;row.hrs+=r.hrs;const ar=T.byA[l.area||c.area||'']=T.byA[l.area||c.area||'']||{mat:0,lab:0,oth:0,hrs:0};ar.mat+=r.m;ar.lab+=r.lb;ar.hrs+=r.hrs;const cc=T.byCC[l.cc||'']=T.byCC[l.cc||'']||{mat:0,lab:0,oth:0};cc.mat+=r.m;cc.lab+=r.lb});T.mat+=row.mat;T.lab+=row.lab;T.hrs+=row.hrs;T.byC[c.id]=row});
  bd.extra.forEach(x=>{const t=num(x.q)*num(x.p);if(!altOn(bd,x.alt)){const a=T.byAlt[x.alt]=T.byAlt[x.alt]||{mat:0,lab:0,oth:0};a.oth+=t;return}T[x.cat||'eqp']+=t;const ar=T.byA[x.area||'']=T.byA[x.area||'']||{mat:0,lab:0,oth:0,hrs:0};ar.oth+=t;const cc=T.byCC[x.cc||'']=T.byCC[x.cc||'']||{mat:0,lab:0,oth:0};cc.oth+=t});
  T.esc=T.mat*num(bd.esc)/100;T.tax=(T.mat+T.esc)*num(bd.tax)/100;T.matX=T.mat+T.esc+T.tax;
  T.ind={stock:T.lab*num(bd.ind.stock)/100,clean:T.lab*num(bd.ind.clean)/100,sup:T.lab*num(bd.ind.sup)/100,pd:num(bd.ind.pd)*T.hrs/num(bd.hpd||8)};T.indT=Object.values(T.ind).reduce((a,b)=>a+b,0);
  const G=bd.mm==='gross';const up=(v,pct)=>G?v/(1-Math.min(.95,num(pct)/100))-v:v*num(pct)/100;T.cat={};T.cost=0;T.ohT=0;T.prT=0;
  CAT.forEach(([k])=>{const cost=k==='mat'?T.matX:T[k];const m=bd.mk[k]||{};const oh=up(cost,m.oh??bd.oh),pr=up(cost+oh,m.profit??bd.profit);T.cat[k]={cost,oh,pr,tot:cost+oh+pr};T.cost+=cost;T.ohT+=oh;T.prT+=pr});
  {const oh=up(T.indT,bd.oh),pr=up(T.indT+oh,bd.profit);T.cat.ind={cost:T.indT,oh,pr,tot:T.indT+oh+pr};T.cost+=T.indT;T.ohT+=oh;T.prT+=pr}
  let run=T.cost+T.ohT+T.prT;T.addT=0;T.addRows=bd.add.map(a=>{const base=a.on==='cost'?T.cost:run;const v=a.type==='amt'?num(a.v):a.type==='perk'?base/1000*num(a.v):base*num(a.v)/100;run+=v;T.addT+=v;return {a,v}});
  T.op=run*num(bd.op)/100;T.tot=run+T.op;T.rnd=num(bd.rnd)?Math.ceil(T.tot/num(bd.rnd))*num(bd.rnd):T.tot;T.sq=num(bd.cover.sq)||p.conds.filter(c=>c.type==='area').reduce((a,c)=>a+condQty(p,c).q,0)/100;T.days=T.hrs/num(bd.hpd||8);return T}
