function undo(){const p=cur();const h=S.hist.pop();if(!h)return;S.redo.push(JSON.stringify(p.bid));p.bid=JSON.parse(h);save();render()}
function redo(){const p=cur();const h=S.redo.pop();if(!h)return;S.hist.push(JSON.stringify(p.bid));p.bid=JSON.parse(h);save();render()}
const ch=f=>{hist();f();save();render()};
/* ---------- list / shell ---------- */
function list(){setCur(null);B.innerHTML=`<div class="mplhead"><h2>Bid</h2><span class="muted" style="font-size:12px">Draft · only you</span><span style="flex:1"></span><button class="btn" id="bdMaster">Master Items</button><button class="btn" id="bdPayM">Payroll defaults</button>${vSeg()}</div>${projList('bid')}`;bindV(B,list);
  B.querySelectorAll('[data-bp]').forEach(b=>b.onclick=()=>{setCur(getPJ().find(p=>p._id===b.dataset.bp));S.tab='cond';S.cid='';render()});B.querySelectorAll('[data-pdel]').forEach(b=>b.onclick=async e=>{e.stopPropagation();await delProject(b.dataset.pdel);list()});B.querySelector('#bdMaster').onclick=masterDlg;B.querySelector('#bdPayM').onclick=()=>payrollDlg(true)}
function render(){const p=cur();if(!p){list();return}const bd=bd_(p);const T=calc(p);if(!S.cid||!p.conds.some(c=>c.id===S.cid))S.cid=(p.conds[0]||{}).id||'';
  B.innerHTML=`<div class="osttabs"><button type="button" id="bdBack">Bids</button>${[['cover','Cover Sheet'],['cond','Conditions'],['mat','Materials'],['lab','Labor'],['pay','Payroll'],['oth','Subs / Equip / Other'],['mk','Markups'],['alt','Alternates'],['rep','Reports'],['prop','Proposal']].map(([k,l])=>`<button type="button" data-bt="${k}" aria-pressed="${S.tab===k}">${l}</button>`).join('')}<span class="osttitle"><b>${esc(p.no||'')} ${esc(p.name)}</b> <small class="muted">${esc(bd.cover.status||'Bidding')}</small></span><span class="qbtot" title="Bid Amount">${money(T.rnd)}</span><button type="button" class="btn small" id="bdUndo" title="Undo (Ctrl+Z)" ${S.hist.length?'':'disabled'}>↶</button><button type="button" class="btn small" id="bdRedo" title="Redo (Ctrl+Y)" ${S.redo.length?'':'disabled'}>↷</button><button type="button" class="btn small plFsB"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 9V4h5M20 9V4h-5M4 15v5h5M20 15v5h-5"/></svg></button></div><div id="bdPane"></div>`;
  B.querySelector('#bdBack').onclick=list;B.querySelectorAll('[data-bt]').forEach(b=>b.onclick=()=>{S.tab=b.dataset.bt;render()});B.querySelector('#bdUndo').onclick=undo;B.querySelector('#bdRedo').onclick=redo;
  const pane=B.querySelector('#bdPane');({cover,cond:conditions,mat:materials,lab:labor,pay:payroll,oth:others,mk:markups,alt:alternates,rep:reports,prop:proposal})[S.tab](pane,p,bd,T)}
