  pane.querySelectorAll('[data-qc]').forEach(r=>r.onclick=()=>{S.cid=r.dataset.qc;render()});pane.querySelector('#qbTk').onclick=()=>{AME.open('tko');window.__tk.open(p._id,p)};pane.querySelector('#qbImp').onchange=e=>{const f=e.target.files[0];if(f){hist();importQbp(f)}};pane.querySelector('#qbAsmM').onclick=()=>P.libDlg?P.libDlg():toast('Assemblies editor is in plans.js');
